class CevcMacSecurityViolationCauseType(TextualConvention, Integer32):
    description = "An integer value which identifies the cause for the MAC\n        Security Violation.\n        \n        If the system MAC Address limit is exceeded, the\n        cevcMacSecurityViolationCauseType will contain \n        'exceedSystemLimit' value.\n\n        If the Bridge domain limit is exceeded, the\n        cevcMacSecurityViolationCauseType will contain \n        'exceedBdLimit' value.\n\n        If the Service Instance limit is exceeded, the\n        cevcMacSecurityViolationCauseType will contain \n        'exceedSILimit' value.\n\n        If the MAC address is present in the Black list\n        then cevcMacSecurityViolationCauseType will contain \n        'blackListDeny' value."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))
    namedValues = NamedValues(("exceedSystemLimit", 1), ("exceedBdLimit", 2), ("exceedSILimit", 3), ("blackListDeny", 4))

