cevcEvcOperStatus = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 613, 1, 3, 2, 1, 1), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))).clone(namedValues=NamedValues(("unknown", 1), ("active", 2), ("partiallyActive", 3), ("inactive", 4)))).setMaxAccess("readonly")
if mibBuilder.loadTexts: cevcEvcOperStatus.setStatus('current')
if mibBuilder.loadTexts: cevcEvcOperStatus.setDescription("This object specifies the operational status of the EVC:\n\n\n        'unknown'\n            Not enough information available regarding the EVC to\n            determine the operational status at this time or EVC \n            operational status is undefined.\n\n        'active'\n            Fully operational between the UNIs in the EVC.  \n\n\n        'partiallyActive'\n            Capable of transferring traffic among some but not all\n            of the UNIs in the EVC.  This operational status is\n            applicable only for Multipoint-to-Multipoint EVCs.\n\n\n        'inactive'\n            Not capable of transferring traffic among any of the\n            UNIs in the EVC.  \n\n        This value is derived from data gathered by underlying OAM\n        protocol.")
